<?php
namespace qqworld_collector\module\collecting\method; use qqworld_collector\lib; class random extends lib { var $guid = 'random'; public function __construct() { add_filter( 'qqworld-collector-collecting-method-' . $this->guid, array($this, 'parse') ); } public function parse($value) { $value = apply_filters( 'qqworld-collector-collection-project-variable-filter', $value, 0 ); $value = explode('-', trim($value)); if (count($value) == 2 && is_numeric($value[0]) && is_numeric($value[1])) { $min = intval($value[0]); $max = intval($value[1]); } else { $min = 1; $max = 1000; } $results = rand($min, $max); return $results; } } ?>